"use strict";let SITE_CONFIG={},ALL_PRODUCTS=[];function getAssetBasePath(){const t=document.currentScript||document.querySelector('script[src*="data.js"], script[src*="data.min.js"]');if(!t)return"";return(t.getAttribute("src")||"").replace(/assets\/js\/data(?:\.min)?\.js(?:\?.*)?$/,"")}function resolveAssetPath(t){const o=getAssetBasePath();return new URL(`${o}${t}`,window.location.href).href}function isLocalFileProtocol(){return"file:"===window.location.protocol}function loadDataScript(t,o){const e=o();return e?Promise.resolve(e):new Promise((e,r)=>{const a=document.createElement("script");a.src=resolveAssetPath(t),a.onload=()=>e(o()),a.onerror=()=>r(new Error(`Failed to load ${t}`)),document.head.appendChild(a)})}function fetchJson(t){const o=resolveAssetPath(t);return fetch(o).then(o=>{if(!o.ok)throw new Error(`Failed to load ${t}`);return o.json()})}function loadSiteConfig(){return isLocalFileProtocol()?loadDataScript("assets/data/site-config.js",()=>window.MKBAGS_SITE_CONFIG):fetchJson("assets/data/site-config.json").catch(()=>loadDataScript("assets/data/site-config.js",()=>window.MKBAGS_SITE_CONFIG))}function loadProducts(){return isLocalFileProtocol()?loadDataScript("assets/data/catalog.data.js",()=>window.MKBAGS_PRODUCTS):fetchJson("assets/data/products.json").catch(()=>loadDataScript("assets/data/catalog.data.js",()=>window.MKBAGS_PRODUCTS))}const dataReady=Promise.all([loadSiteConfig(),loadProducts()]).then(([t,o])=>{SITE_CONFIG=t||{},ALL_PRODUCTS=Array.isArray(o)?o:[]});function formatPrice(t){return(SITE_CONFIG.currencySymbol||"PKR ")+t}function getProductById(t){return ALL_PRODUCTS.find(o=>o.id===Number(t))}function getTrendingProducts(){return ALL_PRODUCTS.filter(t=>t.trending)}function isProductAvailable(t){return t&&"out-of-stock"!==t.stock}